[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param(
 [ValidateSet('Check','Capture','DryRun','Apply','Verify','VerifyReboot','Rollback')][string]$Action='Check',
 [string]$StatePath="$env:ProgramData\Lacksan\EXP-066-hpnetwork-state.json",
 [string]$LogPath="$env:ProgramData\Lacksan\EXP-066-hpnetwork-events.jsonl"
)
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$Experiment='EXP-066';$Provider='hp-network-hsa-manual';$ServiceName='HPNetworkCap'
$ProtectedServices=@('WinDefend','mpssvc','BFE','wuauserv','UsoSvc','BITS','TermService','Tailscale')
function Event([string]$Event,[string]$Result,$Before=$null,$After=$null,[string]$Reason=$null,[string]$Failure=$null){if([string]::IsNullOrWhiteSpace($LogPath)){return};$p=Split-Path -Parent $LogPath;if($p-and!(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null};[ordered]@{schemaVersion=1;timestampUtc=(Get-Date).ToUniversalTime().ToString('o');experiment=$Experiment;provider=$Provider;machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;action=$Action;event=$Event;result=$Result;before=$Before;after=$After;refusalReason=$Reason;failureDetail=$Failure;evidenceStatus='needs-evidence'}|ConvertTo-Json -Compress -Depth 30|Add-Content -LiteralPath $LogPath -Encoding UTF8}
function Elevated{([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)}
function Hash([string]$Text){$s=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($s.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)))).Replace('-','')}finally{$s.Dispose()}}
function Same($A,$B){($A|ConvertTo-Json -Compress -Depth 30)-eq($B|ConvertTo-Json -Compress -Depth 30)}
function ResolveExe([string]$PathName){$m=[regex]::Match([Environment]::ExpandEnvironmentVariables($PathName),'^\s*(?:"(?<p>[^"]+\.exe)"|(?<p>[^\s]+\.exe))');if(!$m.Success){return $null};try{[IO.Path]::GetFullPath($m.Groups['p'].Value)}catch{$null}}
function FileIdentity([string]$Path){if(!(Test-Path -LiteralPath $Path -PathType Leaf)){return $null};$f=Get-Item $Path;$sig=Get-AuthenticodeSignature $Path;$pub=if($sig.SignerCertificate){$sig.SignerCertificate.Subject}else{$null};[pscustomobject]@{Path=$f.FullName;Sha256=(Get-FileHash $Path -Algorithm SHA256).Hash;FileVersion=$f.VersionInfo.FileVersion;ProductVersion=$f.VersionInfo.ProductVersion;CompanyName=$f.VersionInfo.CompanyName;SignatureStatus=$sig.Status.ToString();Publisher=$pub;Thumbprint=if($sig.SignerCertificate){$sig.SignerCertificate.Thumbprint}else{$null};HPSigned=($sig.Status-eq'Valid'-and$pub-match'(?i)HP Inc|Hewlett-Packard')}}
function Management{$cs=Get-CimInstance Win32_ComputerSystem;$ccm=[bool](Get-Service CcmExec -ErrorAction SilentlyContinue);$en=@(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Enrollments' -ErrorAction SilentlyContinue|Where-Object{$_.PSChildName-match'^[0-9A-Fa-f-]{36}$'}).Count;$om=@(Get-ChildItem 'HKLM:\SOFTWARE\Microsoft\Provisioning\OMADM\Accounts' -ErrorAction SilentlyContinue|Where-Object{$_.PSChildName-match'^[0-9A-Fa-f-]{36}$'}).Count;[pscustomobject]@{Managed=([bool]$cs.PartOfDomain-or$ccm-or($en-gt0-and$om-gt0));DomainJoined=[bool]$cs.PartOfDomain;ConfigMgr=$ccm;EnrollmentCount=$en;OmadmCount=$om}}
function PendingReboot{$paths=@('HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending','HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired');foreach($p in $paths){if(Test-Path $p){return $true}};$false}
function Delayed{$p="HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName";$v=Get-ItemProperty $p -Name DelayedAutoStart -ErrorAction SilentlyContinue;[pscustomobject]@{Exists=($null-ne$v);Value=if($null-ne$v){[int]$v.DelayedAutoStart}else{$null}}}
function ServiceState{$svc=Get-CimInstance Win32_Service -Filter "Name='$ServiceName'" -ErrorAction SilentlyContinue;if(!$svc){return $null};$g=Get-Service $ServiceName;$reg=Get-Item "HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName";$type=(Get-ItemProperty $reg.PSPath -Name Type -ErrorAction Stop).Type;[pscustomobject]@{Name=$svc.Name;DisplayName=$svc.DisplayName;StartMode=$svc.StartMode;State=$svc.State;StartName=$svc.StartName;PathName=$svc.PathName;ServiceType=$svc.ServiceType;RegistryType=[int]$type;DelayedAutoStart=Delayed;Dependencies=@($g.ServicesDependedOn|Select-Object -ExpandProperty Name|Sort-Object);Dependents=@($g.DependentServices|Select-Object -ExpandProperty Name|Sort-Object);Recovery=((& sc.exe qfailure $ServiceName 2>&1|Out-String).Trim());Triggers=((& sc.exe qtriggerinfo $ServiceName 2>&1|Out-String).Trim());RegistryOwner=(Get-Acl $reg.PSPath).Owner}}
function ProtectedState{@($ProtectedServices|ForEach-Object{Get-CimInstance Win32_Service -Filter "Name='$_'" -ErrorAction SilentlyContinue}|Where-Object{$_}|Sort-Object Name|Select-Object Name,StartMode,State,PathName)}
function NetworkState{$a=@(Get-NetAdapter -IncludeHidden -ErrorAction SilentlyContinue|Sort-Object InterfaceGuid,Name|Select-Object Name,InterfaceDescription,InterfaceGuid,InterfaceIndex,Status,MacAddress);$b=@(Get-NetAdapterBinding -AllBindings -ErrorAction SilentlyContinue|Sort-Object InterfaceDescription,ComponentID|Select-Object InterfaceDescription,ComponentID,DisplayName,Enabled);$ip=@(Get-NetIPAddress -ErrorAction SilentlyContinue|Sort-Object InterfaceIndex,AddressFamily,IPAddress|Select-Object InterfaceIndex,AddressFamily,IPAddress,PrefixLength,PrefixOrigin,SuffixOrigin);$r=@(Get-NetRoute -ErrorAction SilentlyContinue|Sort-Object InterfaceIndex,AddressFamily,DestinationPrefix,NextHop|Select-Object InterfaceIndex,AddressFamily,DestinationPrefix,NextHop,RouteMetric,Protocol);$d=@(Get-DnsClientServerAddress -ErrorAction SilentlyContinue|Sort-Object InterfaceIndex,AddressFamily|Select-Object InterfaceIndex,AddressFamily,ServerAddresses);$p=@(Get-NetConnectionProfile -ErrorAction SilentlyContinue|Sort-Object InterfaceIndex|Select-Object Name,InterfaceAlias,InterfaceIndex,NetworkCategory,IPv4Connectivity,IPv6Connectivity);$proxy=((& netsh winhttp show proxy 2>&1|Out-String).Trim());[pscustomobject]@{Adapters=$a;Bindings=$b;IPAddresses=$ip;Routes=$r;Dns=$d;Profiles=$p;WinHttpProxy=$proxy}}
function HPApps{$u=@();foreach($root in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*','HKCU:\Software\Microsoft\Windows\CurrentVersion\Uninstall\*'){$u+=@(Get-ItemProperty $root -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName-match'(?i)(OMEN Gaming Hub|OMEN Command Center|HP.*Network)' }|Select-Object DisplayName,DisplayVersion,Publisher,InstallLocation)};$appx=@(Get-AppxPackage -ErrorAction SilentlyContinue|Where-Object{$_.Name+$_.PackageFamilyName-match'(?i)OMEN|HP.*Network'}|Select-Object Name,PackageFamilyName,Version,Publisher);[pscustomobject]@{Uninstall=@($u|Sort-Object DisplayName);Appx=@($appx|Sort-Object Name)}}
function Packages{$u=@();foreach($root in 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Uninstall\*','HKLM:\SOFTWARE\WOW6432Node\Microsoft\Windows\CurrentVersion\Uninstall\*'){$u+=@(Get-ItemProperty $root -ErrorAction SilentlyContinue|Where-Object{$_.DisplayName-match'(?i)HP.*(Network|System Event|Hotkey|Support|Capability)' }|Select-Object DisplayName,DisplayVersion,Publisher,InstallLocation,PSPath)};@($u|Sort-Object DisplayName)}
function Support{$os=Get-CimInstance Win32_OperatingSystem;$cs=Get-CimInstance Win32_ComputerSystem;$mg=Management;$st=ServiceState;$apps=HPApps;$reasons=@();$id=$null;if($os.Caption-notmatch'Windows 11'){$reasons+='Windows 11 required.'};if($cs.Manufacturer-notmatch'(?i)^HP$|Hewlett-Packard'){$reasons+='HP platform required.'};if(!(Elevated)){$reasons+='Elevation required.'};if(PendingReboot){$reasons+='Pending reboot detected.'};if($mg.Managed){$reasons+='Enterprise management ownership detected.'};if(!$st){$reasons+='HPNetworkCap service required.'}else{$exe=ResolveExe $st.PathName;$id=if($exe){FileIdentity $exe}else{$null};if($st.DisplayName-notmatch'(?i)HP Network HSA Service'){$reasons+='Unexpected service display identity.'};if(!$id-or!$id.HPSigned){$reasons+='Valid HP-signed NetworkCap executable required.'};if($st.RegistryType-band 1){$reasons+='Kernel or driver-backed service identity refused.'};if($st.StartMode-eq'Disabled'){$reasons+='Disabled service refused.'};if($st.Dependents.Count-gt0){$reasons+='Dependent services make this candidate dependency-sensitive.'};if(@($st.Dependencies|Where-Object{$_-in$ProtectedServices}).Count-gt0){$reasons+='Protected dependency edge detected.'}};if($apps.Uninstall.Count-gt0-or$apps.Appx.Count-gt0){$reasons+='OMEN or HP network application presence requires physical demand-start qualification.'};[pscustomobject]@{Supported=($reasons.Count-eq0);Reasons=$reasons;OS=$os.Caption;Build=$os.BuildNumber;Manufacturer=$cs.Manufacturer;Model=$cs.Model;Elevated=(Elevated);PendingReboot=(PendingReboot);Management=$mg;ServiceState=$st;Executable=$id;Packages=Packages;HPApplications=$apps;Network=NetworkState;Protected=ProtectedState;EvidenceStatus='needs-evidence'}}
function Save($s){if(!$s.Supported){throw($s.Reasons-join' ')};if(Test-Path $StatePath){throw 'State overwrite refused.'};$p=Split-Path -Parent $StatePath;if($p-and!(Test-Path $p)){New-Item -ItemType Directory -Path $p -Force|Out-Null};$o=[ordered]@{schemaVersion=1;experiment=$Experiment;provider=$Provider;capturedUtc=(Get-Date).ToUniversalTime().ToString('o');capturedBootUtc=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime().ToString('o');machine=$env:COMPUTERNAME;userSid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;original=$s.ServiceState;executable=$s.Executable;packages=$s.Packages;hpApplications=$s.HPApplications;management=$s.Management;networkHash=Hash($s.Network|ConvertTo-Json -Compress -Depth 30);network=$s.Network;protectedHash=Hash($s.Protected|ConvertTo-Json -Compress -Depth 20);evidenceStatus='needs-evidence'};$o|ConvertTo-Json -Depth 30|Set-Content $StatePath -Encoding UTF8;[pscustomobject]$o}
function Read{if(!(Test-Path $StatePath)){throw 'Captured state required.'};$s=Get-Content $StatePath -Raw|ConvertFrom-Json;$sid=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;if($s.schemaVersion-ne1-or$s.experiment-ne$Experiment-or$s.provider-ne$Provider-or$s.machine-ne$env:COMPUTERNAME-or$s.userSid-ne$sid){throw 'State identity validation failed.'};$s}
function Drift($s){if((Management).Managed){throw 'Management ownership drift detected.'};if(PendingReboot){throw 'Pending reboot drift detected.'};$now=ServiceState;if(!$now){throw 'Service identity drift detected.'};$id=FileIdentity (ResolveExe $now.PathName);if(!$id-or!$id.HPSigned-or$id.Sha256-ne[string]$s.executable.Sha256-or$id.Thumbprint-ne[string]$s.executable.Thumbprint-or$id.FileVersion-ne[string]$s.executable.FileVersion){throw 'Executable identity drift detected.'};if(!(Same $now.Dependencies $s.original.Dependencies)-or!(Same $now.Dependents $s.original.Dependents)-or$now.PathName-ne[string]$s.original.PathName-or$now.StartName-ne[string]$s.original.StartName-or$now.Recovery-ne[string]$s.original.Recovery-or$now.Triggers-ne[string]$s.original.Triggers){throw 'Service configuration drift detected.'};if((Hash((NetworkState)|ConvertTo-Json -Compress -Depth 30))-ne[string]$s.networkHash){throw 'Network stack drift detected.'};if((Hash((ProtectedState)|ConvertTo-Json -Compress -Depth 20))-ne[string]$s.protectedHash){throw 'Protected configuration drift detected.'};$apps=HPApps;if($apps.Uninstall.Count-gt0-or$apps.Appx.Count-gt0){throw 'HP application boundary drift detected.'};$now}
function SetManual{$out=& sc.exe config $ServiceName start= demand 2>&1;if($LASTEXITCODE-ne0){throw("sc.exe config failed: "+($out-join' '))};Remove-ItemProperty "HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName" -Name DelayedAutoStart -ErrorAction SilentlyContinue}
function Treatment{$s=ServiceState;$s.StartMode-eq'Manual'-and!$s.DelayedAutoStart.Exists}
function Restore($s){$start=if($s.original.StartMode-eq'Auto'){'auto'}elseif($s.original.StartMode-eq'Manual'){'demand'}else{throw 'Unsupported original startup mode.'};$out=& sc.exe config $ServiceName start= $start 2>&1;if($LASTEXITCODE-ne0){throw("startup rollback failed: "+($out-join' '))};$p="HKLM:\SYSTEM\CurrentControlSet\Services\$ServiceName";if($s.original.DelayedAutoStart.Exists){New-ItemProperty $p -Name DelayedAutoStart -PropertyType DWord -Value ([int]$s.original.DelayedAutoStart.Value) -Force|Out-Null}else{Remove-ItemProperty $p -Name DelayedAutoStart -ErrorAction SilentlyContinue};$svc=Get-Service $ServiceName;if([string]$s.original.State-eq'Running'-and$svc.Status-ne'Running'){Start-Service $ServiceName}elseif([string]$s.original.State-ne'Running'-and$svc.Status-eq'Running'){Stop-Service $ServiceName -Force:$false}}
try{$support=Support;Event 'support-detection' $(if($support.Supported){'pass'}else{'refused'}) $null $support ($(if($support.Supported){$null}else{$support.Reasons-join' '}));switch($Action){'Check'{$support};'Capture'{$s=Save $support;Event 'capture' 'pass' $null $s;$s};'DryRun'{if(!$support.Supported){throw($support.Reasons-join' ')};$r=[pscustomobject]@{WouldChange=$true;MutationCount=1;ServiceName=$ServiceName;TargetStartMode='Manual';PreserveCurrentRunningState=$true;NetworkMutationCount=0;RebootPersistenceRequired=$true;HPDemandStart='needs-evidence';DnsHttpsReadiness='needs-evidence';ProtectedApplicationReadiness='needs-evidence';Rollback='Restore exact captured startup mode, delayed-auto-start state, and original running state after service, executable, management, network, HP application, and protected-scope drift checks.';EvidenceStatus='needs-evidence'};Event 'dry-run' 'pass' $support.ServiceState $r;$r};'Apply'{$s=if(Test-Path $StatePath){Read}else{Save $support};$before=Drift $s;if(Treatment){Event 'apply' 'idempotent' $before $before;return [pscustomobject]@{Applied=$true;MutationCount=0}};$running=([string]$before.State-eq'Running');if($WhatIfPreference){Event 'apply' 'whatif' $before $before;return [pscustomobject]@{Applied=$false;WhatIf=$true;MutationCount=0}};if($PSCmdlet.ShouldProcess($ServiceName,'Change HP Network HSA Service startup mode to Manual while preserving running state')){SetManual}else{return};$after=ServiceState;if(!(Treatment)-or$running-ne([string]$after.State-eq'Running')){throw 'Application verification failed.'};if((Hash((NetworkState)|ConvertTo-Json -Compress -Depth 30))-ne[string]$s.networkHash){throw 'Network stack changed during application.'};Event 'apply' 'pass' $before $after;$after};'Verify'{$s=Read;$before=Drift $s;if(!(Treatment)){throw 'Treatment verification failed.'};$r=[pscustomobject]@{Verified=$true;Service=$before;NetworkStackPreserved=$true;HPDemandStart='needs-evidence';DnsHttpsReadiness='needs-evidence';ProtectedApplicationReadiness='needs-evidence';DeviceManager='needs-evidence'};Event 'verify' 'pass' $before $r;$r};'VerifyReboot'{$s=Read;$boot=(Get-CimInstance Win32_OperatingSystem).LastBootUpTime.ToUniversalTime();if($boot-le[datetime]$s.capturedBootUtc){throw 'A later boot is required.'};$before=Drift $s;if(!(Treatment)){throw 'Reboot persistence failed.'};$r=[pscustomobject]@{VerifiedReboot=$true;BootUtc=$boot.ToString('o');NetworkStackPreserved=$true;HPDemandStart='needs-evidence';DnsHttpsReadiness='needs-evidence';ProtectedApplicationReadiness='needs-evidence'};Event 'verify-reboot' 'pass' $before $r;$r};'Rollback'{$s=Read;$before=Drift $s;if($before.StartMode-eq[string]$s.original.StartMode-and(Same $before.DelayedAutoStart $s.original.DelayedAutoStart)-and$before.State-eq[string]$s.original.State){Event 'rollback' 'idempotent' $before $before;return [pscustomobject]@{RolledBack=$true;MutationCount=0}};if(!(Treatment)){throw 'Rollback collision detected; treatment state changed.'};if($WhatIfPreference){Event 'rollback' 'whatif' $before $before;return [pscustomobject]@{RolledBack=$false;WhatIf=$true;MutationCount=0}};if($PSCmdlet.ShouldProcess($ServiceName,'Restore exact EXP-066 service startup and running state')){Restore $s}else{return};$after=ServiceState;if($after.StartMode-ne[string]$s.original.StartMode-or!(Same $after.DelayedAutoStart $s.original.DelayedAutoStart)-or$after.State-ne[string]$s.original.State){throw 'Exact rollback verification failed.'};if((Hash((NetworkState)|ConvertTo-Json -Compress -Depth 30))-ne[string]$s.networkHash){throw 'Network stack changed during rollback.'};Event 'rollback' 'pass' $before $after;$after}}}catch{Event 'failure' 'failure' $null $null $null $_.Exception.Message;throw}
